{
  "root_causes": [
    {
      "service": "ts-travel2-service",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT CASE WHEN c.duration/1e6>50 THEN 'slow' ELSE 'fast' END bucket, count(*) n, approx_quantile(c.duration/1e6,0.5) c_p50, approx_quantile(s.duration/1e6,0.5) s_p50, approx_quantile(epoch_ms(s.time)-epoch_ms(c.time),0.5) start_off_ms, approx_quantile((epoch_ms(c.time)+c.duration/1e6)-(epoch_ms(s.time)+s.duration/1e6),0.5) end_gap_ms FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND s.parent_span_id=c.span_id WHERE c.attr_span_kind='Client' AND c.service_name='ts-travel2-service' AND s.service_name='ts-route-service' GROUP BY 1",
          "claim": "Slow travel2 GET calls to route-service take about 209ms, but the server starts about 208ms late and responds in about 1.6ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration/1e6,0.5) p50, approx_quantile(duration/1e6,0.95) p95 FROM abnormal_traces WHERE service_name='ts-travel2-service' AND attr_span_kind='Client' AND span_name IN ('GET','POST') GROUP BY ALL",
          "claim": "travel2 GET client spans have a p95 of about 217ms, while its POST client spans stay near 14ms, as in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, service_name, span_name, count(*) n, approx_quantile(duration/1e6,0.95) p95_ms FROM abnormal_traces WHERE service_name='ts-travel2-service' AND span_name='Travel2Controller.adminQueryAll' GROUP BY 1,2,3",
          "claim": "travel2's adminQueryAll internal span has a p95 of about 3.5s, versus a few milliseconds for its other internal spans."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel2-service",
      "to": "ts-admin-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, c.service_name caller, s.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.95) caller_p95_ms, approx_quantile(s.duration/1e6,0.95) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='ts-admin-travel-service' AND s.service_name='ts-travel2-service' AND s.attr_span_kind='Server' GROUP BY 1,2,3",
          "claim": "admin-travel's calls into travel2 rise from about 32ms p95 in normal to about 1864ms in abnormal."
        }
      ]
    },
    {
      "from": "ts-admin-travel-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, c.service_name caller, s.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.95) caller_p95_ms, approx_quantile(s.duration/1e6,0.95) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='ts-ui-dashboard' AND s.service_name='ts-admin-travel-service' AND s.attr_span_kind='Server' GROUP BY 1,2,3",
          "claim": "ui-dashboard's calls to admin-travel rise from about 64ms p95 in normal to about 1543ms in abnormal."
        }
      ]
    }
  ]
}
